class Solution {
public:
    std::vector<std::vector<int>> removeInterval(std::vector<std::vector<int>>& intervals, std::vector<int>& toBeRemoved) {
        int rStart = toBeRemoved[0], rEnd = toBeRemoved[1];
        std::vector<std::vector<int>> res;
        for (const auto& iv : intervals) {
            int start = iv[0], end = iv[1];
            if (end <= rStart || start >= rEnd) {
                res.push_back({start, end});
            } else {
                if (start < rStart) res.push_back({start, rStart});
                if (end > rEnd) res.push_back({rEnd, end});
            }
        }
        return res;
    }
};

class Solution {
    public java.util.List<java.util.List<Integer>> removeInterval(int[][] intervals, int[] toBeRemoved) {
        int rStart = toBeRemoved[0], rEnd = toBeRemoved[1];
        java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
        for (int[] iv : intervals) {
            int start = iv[0], end = iv[1];
            if (end <= rStart || start >= rEnd) {
                res.add(java.util.List.of(start, end));
            } else {
                if (start < rStart) res.add(java.util.List.of(start, rStart));
                if (end > rEnd) res.add(java.util.List.of(rEnd, end));
            }
        }
        return res;
    }
}

var removeInterval = function(intervals, toBeRemoved) {
    const [rStart, rEnd] = toBeRemoved;
    const res = [];
    for (const [start, end] of intervals) {
        if (end <= rStart || start >= rEnd) {
            res.push([start, end]);
        } else {
            if (start < rStart) res.push([start, rStart]);
            if (end > rEnd) res.push([rEnd, end]);
        }
    }
    return res;
};
